var Particle = function (position) {
  this.velocity = createVector(random(-3,3), random(-3,3));
  this.position = position.copy();

  this.draw = function () {
    //TODO: Find a pretty way to render particles.
    fill(255,255,255,3)
    stroke(0,0,0,0);
    for (var i = 0; i < 50/3; i++) {
      ellipse(this.position.x, this.position.y, i*3, i*3);
    }
  }

  this.update = function () {
    this.position.add(this.velocity);

    if (this.position.x < 0) {
      this.position.x = windowWidth;
    }
    if (this.position.x > windowWidth) {
      this.position.x = 0;
    }
    if (this.position.y < 0) {
      this.position.y = windowHeight;
    }
    if (this.position.y > windowHeight) {
      this.position.y = 0;
    }
  }
}

var ParticleSystem = function (particleCount, posFunc) {
  this.particles = [];

  for (var i = 0; i < particleCount; i++) {
    this.particles.push(new Particle(posFunc()));
  }

  this.run = function () {
    for (var a in this.particles) {
      var currPart = this.particles[a];
      for (var b in this.particles) {
        var nextPart = this.particles[b];
        var closeness = 250/dist(currPart.position.x, currPart.position.y, nextPart.position.x, nextPart.position.y)

        if (dist(currPart.position.x, currPart.position.y, nextPart.position.x, nextPart.position.y) < 255) {
          stroke(255,255,255,closeness*7)
          line(currPart.position.x, currPart.position.y, nextPart.position.x, nextPart.position.y);
        }
      }
    }

    for (var a in this.particles) {
      var currPart = this.particles[a];

      currPart.draw();
      currPart.update();
    }
  }
}

var system;

function setup() {
  createCanvas(windowWidth, windowHeight); 
  frameRate(30);

  system = new ParticleSystem(100, function () {
    return createVector(random(0,windowWidth), random(0,windowHeight));
  });
} 

function draw() {
  background(0,0,15);

  system.run();
}

